using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using ConsoleTables;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00020 : ControllerTestBase
    {
        [DataTestMethod]
        [DataRow("get")]
        [DataRow("post")]
        [DataRow("patch")]
        [DataRow("put")]
        [DataRow("delete")]
        [DataRow("_")]
        public void Method_Route_Declarations_Should_Not_Contains_Forbidden_Words_Or_Forbidden_Chars(string word)
        {
            var missingVersionPlaceholder = (from controller in Controllers
                                             from method in controller.Methods
                                             from attribute in method.Attributes
                                             where attribute.Name.Contains("Route") || attribute.Name.StartWith("Http") &&
                                                 attribute.Arguments.Any(a => a.Contains(word))
                                             select new
                                             {
                                                 Controller = controller.FullQualifiedName, 
                                                 MethodName = method.Name,
                                                 Method = method.MethodValue,
                                                 Attribute = attribute.SyntaxTree
                                             }).ToImmutableList();


            Assert.IsTrue(missingVersionPlaceholder.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00020

Route template contains invalid word or character: {word}:{Environment.NewLine}{ConsoleTable.From(missingVersionPlaceholder)}");
        }
    }
